#include <iostream>
#include <array>
#include <utility>
#include <iomanip>

template <typename T, std::size_t Size>
void modernSelectionSort(std::array<T, Size>& items) {
    for (std::size_t i = 0; i < items.size() - 1; ++i) {
        std::size_t indexOfSmallest = i;
        for (std::size_t index = i + 1; index < items.size(); ++index) {
            if (items[index] < items[indexOfSmallest]) {
                indexOfSmallest = index;
            }
        }
        if (indexOfSmallest != i) {
            std::swap(items[i], items[indexOfSmallest]);
        }
    }
}

int main() {
    const std::size_t arraySize = 10;
    std::array<int, arraySize> data = {34, 56, 4, 10, 77, 51, 93, 30, 5, 52};

    std::cout << "Unsorted array:\n";
    for (const auto& val : data) {
        std::cout << std::setw(4) << val;
    }
    std::cout << "\n";

    modernSelectionSort(data);

    std::cout << "Sorted array:\n";
    for (const auto& val : data) {
        std::cout << std::setw(4) << val;
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <vector>

// Demonstrates two-way merging of two already sorted sequences
std::vector<int> mergeSubarrays(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> combined;
    combined.reserve(a.size() + b.size());

    std::size_t i = 0;
    std::size_t j = 0;

    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) {
            combined.push_back(a[i++]);
        } else {
            combined.push_back(b[j++]);
        }
    }

    while (i < a.size()) {
        combined.push_back(a[i++]);
    }
    while (j < b.size()) {
        combined.push_back(b[j++]);
    }

    return combined;
}

int main() {
    std::vector<int> subA = {4, 10, 34, 56, 77};
    std::vector<int> subB = {5, 30, 51, 52, 93};

    std::cout << "Subarray A: ";
    for (int x : subA) std::cout << x << " ";
    std::cout << "\nSubarray B: ";
    for (int x : subB) std::cout << x << " ";
    std::cout << "\n";

    std::vector<int> merged = mergeSubarrays(subA, subB);

    std::cout << "Merged:     ";
    for (int x : merged) std::cout << x << " ";
    std::cout << "\n";

    return 0;
}
